"""Structural interfaces (protocols) across the orchestration boundary.

These ``Protocol`` types define the seams used for dependency injection and
testing: the prompt-construction boundary, the skill-engine boundary consumed
by the orchestrator, and the orchestrator itself.  The plain-data payloads they
exchange live in :mod:`rasa.mantle.orchestration.responses`.
"""

from __future__ import annotations

from typing import (
    TYPE_CHECKING,
    List,
    Optional,
    Protocol,
    runtime_checkable,
)

if TYPE_CHECKING:
    from rasa.mantle.state.tracker_handle import TrackerHandle
    from rasa.mantle.state.turn import IncomingTurn

from rasa.mantle.orchestration.responses import AgentResponse, TurnResult
from rasa.mantle.prompts.constructor import PromptContext
from rasa.mantle.prompts.messages import LlmMessage


@runtime_checkable
class PromptConstructorProtocol(Protocol):
    """Define the prompt-construction boundary for turns."""

    def build_messages(self, context: PromptContext) -> List[LlmMessage]:
        """Build LLM chat messages (system, history, current user) for one turn."""
        ...

    def build_rephrase_messages(
        self, context: PromptContext, text_to_rephrase: str
    ) -> List[LlmMessage]:
        """Build messages for a rephrase LLM call (no tools should be passed)."""
        ...

    def build_confirm_rephrase_messages(
        self,
        context: PromptContext,
        text_to_rephrase: str,
        *,
        field_name: str,
        value: object,
        field_description: Optional[str] = None,
    ) -> List[LlmMessage]:
        """Build messages for a filled-collect confirmation rephrase call."""
        ...

    def build_set_fields_fill_messages(
        self, context: PromptContext
    ) -> List[LlmMessage]:
        """Build messages for a silent memory-extraction call."""
        ...


@runtime_checkable
class SkillExecutorProtocol(Protocol):
    """Define the skill-engine boundary consumed by the Orchestrator.

    The SkillExecutor owns all skill/phase/tool semantics and emits tracker
    events directly.  It does **not** own the outer LLM iteration loop.
    """

    async def advance_steps(
        self,
        tracker_handle: TrackerHandle,
        *,
        defer_listen: bool = False,
    ) -> Optional[AgentResponse]:
        """Advance any deterministically completable steps before the LLM call.

        Args:
            tracker_handle: Live tracker wrapper for the current turn.
            defer_listen: When ``True`` and ``action_listen`` is reached with
                settable fields available, return without running it.
                ``hangup`` always commits.

        Returns an ``AgentResponse`` when a step emitted a response that
        the orchestrator must handle (WAIT → break loop; CONTINUE → proceed).
        Returns ``None`` when no pre-LLM output was produced.
        """
        ...

    def completing_delivered_step_ends_active_flow(
        self, tracker_handle: TrackerHandle
    ) -> bool:
        """Return whether ``complete_delivered_step`` would pop the active flow."""
        ...

    async def dispatch_tool_call(
        self,
        tool_name: str,
        tool_args: object,
        tracker_handle: TrackerHandle,
    ) -> Optional[str]:
        """Execute one LLM-requested tool call and return the tool-result string."""
        ...


@runtime_checkable
class OrchestratorProtocol(Protocol):
    """Turn-level coordinator — owns the LLM loop, not skill semantics."""

    async def run_turn(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
    ) -> TurnResult:
        """Execute one full user-message turn and return the outcome.

        Agent responses are emitted through the ambient ``MessageTurnContext``
        established for the duration of the turn (see
        ``rasa.mantle.orchestration.turn_context``).

        Args:
            tracker_handle: Live state wrapper for the current tracker.
            turn: The current incoming user turn.
        """
        ...
